  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior when they are stressed, healing, or asking for attention."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer because growing, playing, and aging all require extra rest."
        },
        {
          question: "Should indoor cats still have enrichment?",
          answer:
            "Yes. Puzzle feeders, climbing spaces, scratching posts, window perches, and daily play sessions help indoor cats stay active and confident."
        },
        {
          question: "Why does my cat knead blankets?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead soft surfaces when they are relaxed, sleepy, or marking a favorite spot."
        },
        {
          question: "What is the best way to introduce a new cat?",
          answer:
            "Introduce cats gradually with scent swapping, separate safe rooms, short supervised visits, and positive rewards. Slow introductions reduce stress and territorial conflict."
        }
      ];

      function Header() {
        return `
          <header>
            <p class="eyebrow">Cat care basics</p>
            <h1>FAQ for curious cat people</h1>
            <p class="intro">
              Quick answers to common questions about feline behavior, comfort,
              and everyday care.
            </p>
          </header>
        `;
      }

      function FAQItem(item, index) {
        const buttonId = `faq-button-${index}`;
        const detailsId = `faq-details-${index}`;

        return `
          <div class="example">
            <h2>
              <button
                class="question"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${detailsId}"
              >
                <span>${item.question}</span>
                <span class="indicator" aria-hidden="true">+</span>
              </button>
            </h2>
            <div
              class="details"
              id="${detailsId}"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `
          <section class="faq-panel" aria-labelledby="faq-heading">
            <h2 id="faq-heading">Frequently asked questions</h2>
            ${items.map(FAQItem).join("")}
          </section>
        `;
      }

      function App() {
        return `
          <div class="page">
            ${Header()}
            <main id="main-content">
              ${FAQList(faqs)}
            </main>
            <footer>
              <strong>Tip:</strong> If your cat's behavior changes suddenly,
              contact a veterinarian to rule out pain, illness, or stress.
            </footer>
          </div>
        `;
      }

      function bindDisclosureControls(root) {
        root.querySelectorAll(".question").forEach((button) => {
          button.addEventListener("click", () => {
            const details = document.getElementById(
              button.getAttribute("aria-controls")
            );
            const isExpanded = button.getAttribute("aria-expanded") === "true";

            button.setAttribute("aria-expanded", String(!isExpanded));
            details.hidden = isExpanded;
          });
        });
      }

      const root = document.getElementById("root");
      root.innerHTML = App();
      bindDisclosureControls(root);
    </script>
  </body>
